cssCode:
.cart-btn {
  width: 180px; height: 50px;
  background: #6c63ff; color: #fff;
  border: none; border-radius: 25px;
  font-size: 16px; font-weight: bold; cursor: pointer;
  transition: all 0.4s ease;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden; box-shadow: 0 4px 15px rgba(108, 99, 255, 0.4);
}
.cart-btn.loading {
  width: 50px; background: transparent;
  border: 4px solid rgba(108, 99, 255, 0.3);
  border-top-color: #6c63ff; color: transparent;
  animation: spinCart 1s linear infinite; pointer-events: none;
}
.cart-btn.success {
  width: 180px; background: #00cc66; color: #fff;
  border: none; animation: none;
  box-shadow: 0 4px 15px rgba(0, 204, 102, 0.4); pointer-events: none;
}
@keyframes spinCart { 100% { transform: rotate(360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const btn = document.createElement('button');
btn.className = 'cart-btn';
btn.innerText = 'ADD TO CART';
c.appendChild(btn);

btn.addEventListener('pointerdown', () => {
  btn.classList.add('loading');
  btn.innerText = '';

  setTimeout(() => {
    btn.classList.remove('loading');
    btn.classList.add('success');
    btn.innerText = 'SUCCESS ✓';

    setTimeout(() => {
      btn.classList.remove('success');
      btn.innerText = 'ADD TO CART';
    }, 2000);
  }, 1500);
});
